final class RedstoneRequesterRenderingTest {
    private static final BlockPos P=new BlockPos(1904,4,6),S=new BlockPos(1900,4,3);
    static void run(ClientGameTestContext context,TestSingleplayerContext world) {
        var server=world.getServer();var id=UUID.randomUUID();server.runCommand("gamemode spectator @p");server.runCommand("tp @p 1904 8 12");context.waitFor(client->Math.abs(client.player.getX()-1904.5)<.1,300);waitChunks(context,world,new BlockPos(1896,3,0),new BlockPos(1927,3,15));server.runCommand("fill 1896 3 0 1927 3 15 minecraft:smooth_quartz");
        server.runOnServer(ignored->{var level=world.getConnection().getServerLevel();station(level,S,id,20);level.setBlockAndUpdate(P,AllBlocks.REDSTONE_REQUESTER.defaultBlockState());var requester=(RedstoneRequesterBlockEntity)level.getBlockEntity(P);requester.behaviour.setFrequency(id);requester.notifyUpdate();level.setBlockAndUpdate(P.east(4),AllBlocks.REDSTONE_REQUESTER.defaultBlockState().setValue(RedstoneRequesterBlock.AXIS,Direction.Axis.Z));});
        context.waitFor(client->client.level.getBlockEntity(P) instanceof RedstoneRequesterBlockEntity requester&&requester.behaviour.freqId.equals(id),200);world.getConnection().waitForChunksRender();
        context.runOnClient(client->{var resolver=new BlockModelResolver(client.getModelManager());for(var state:AllBlocks.REDSTONE_REQUESTER.getStateDefinition().getPossibleStates()){var render=new BlockModelRenderState();resolver.update(render,state,BlockDisplayContext.create());if(render.isEmpty()||client.getModelManager().getBlockStateModelSet().get(state)==client.getModelManager().getBlockStateModelSet().missingModel())throw new AssertionError("Missing requester orientation/power model: "+state);}});
        server.runCommand("tp @p 1904 4 9");context.waitFor(client->Math.abs(client.player.getY()-4)<.1,200);server.runOnServer(ignored->{var player=world.getConnection().getServerLevel().getServer().getPlayerList().getPlayers().getFirst();player.getInventory().clearContent();player.getInventory().setItem(9,new ItemStack(Items.APPLE,12));player.getInventory().setItem(10,new ItemStack(Items.CARROT,4));player.inventoryMenu.broadcastFullState();player.resetFallDistance();player.setHealth(player.getMaxHealth());});server.runCommand("gamemode survival @p");context.waitFor(client->!client.player.isSpectator()&&client.player.getMainHandItem().isEmpty()&&client.player.getInventory().getItem(9).getCount()==12,200);context.getInput().lookAt(P);context.waitFor(client->client.hitResult instanceof BlockHitResult hit&&hit.getBlockPos().equals(P),200);
        open(context);context.getInput().typeChars("Requester A");shiftClick(context,9);context.waitFor(client->client.player.containerMenu.getSlot(0).getItem().is(Items.APPLE),200);shiftClick(context,10);context.waitFor(client->client.player.containerMenu.getSlot(1).getItem().is(Items.CARROT),200);
        var point=context.computeOnClient(client->{var local=((RedstoneRequesterScreen)client.gui.screen()).slotPosition(0);float scaleX=(float)client.getWindow().getScreenWidth()/client.getWindow().getGuiScaledWidth();float scaleY=(float)client.getWindow().getScreenHeight()/client.getWindow().getGuiScaledHeight();return new Vec2(local.x*scaleX,local.y*scaleY);});context.getInput().setCursorPos(point.x,point.y);context.getInput().scroll(1);context.getInput().scroll(1);context.waitTicks(3);context.takeScreenshot("create-vulkan-redstone-requester-native-order");context.clickScreenButton("✓");context.waitFor(client->client.gui.screen()==null&&client.level.getBlockEntity(P) instanceof RedstoneRequesterBlockEntity requester&&requester.encodedTargetAdress.equals("Requester A")&&requester.encodedRequest.stacks().getFirst().count==3,200);
        server.runOnServer(ignored->{var level=world.getConnection().getServerLevel();var requester=(RedstoneRequesterBlockEntity)level.getBlockEntity(P);if(requester.encodedRequest.stacks().size()!=2||requester.encodedRequest.stacks().getFirst().count!=3||!requester.encodedTargetAdress.equals("Requester A"))throw new AssertionError("Native editor settings not saved: "+requester.encodedRequest+" / "+requester.encodedTargetAdress);level.setBlockAndUpdate(P.east(),Blocks.REDSTONE_BLOCK.defaultBlockState());if(!((BarrelBlockEntity)level.getBlockEntity(S.north())).getItem(0).is(Items.APPLE)||((BarrelBlockEntity)level.getBlockEntity(S.north())).getItem(0).getCount()!=20||requester.lastRequestSucceeded)throw new AssertionError("Full request consumed stock with missing carrots");});
        context.waitFor(client->client.level.getBlockState(P).getValue(RedstoneRequesterBlock.POWERED),200);context.waitTicks(5);context.getInput().lookAt(P);context.takeScreenshot("create-vulkan-redstone-requester-denied");open(context);context.clickScreenButton("½");context.clickScreenButton("✓");context.waitFor(client->client.gui.screen()==null&&client.level.getBlockEntity(P) instanceof RedstoneRequesterBlockEntity requester&&requester.allowPartialRequests,200);
        server.runOnServer(ignored->{var level=world.getConnection().getServerLevel();var requester=(RedstoneRequesterBlockEntity)level.getBlockEntity(P);if(!requester.allowPartialRequests)throw new AssertionError("Native partial mode not saved");level.setBlockAndUpdate(P.east(),Blocks.AIR.defaultBlockState());level.setBlockAndUpdate(P.east(),Blocks.REDSTONE_BLOCK.defaultBlockState());var packager=(PackagerBlockEntity)level.getBlockEntity(S);if(PackageItem.getContents(packager.heldBox).stream().mapToInt(ItemStack::getCount).sum()!=3||!PackageItem.getAddress(packager.heldBox).equals("Requester A")||!requester.lastRequestSucceeded)throw new AssertionError("Partial redstone order not sent");});
        context.waitFor(client->client.level.getBlockEntity(P) instanceof RedstoneRequesterBlockEntity requester&&requester.lastRequestSucceeded,200);context.waitTicks(10);server.runOnServer(ignored->{var level=world.getConnection().getServerLevel();var requester=(RedstoneRequesterBlockEntity)level.getBlockEntity(P);for(int i=0;i<8;i++)requester.onRedstonePowerChanged();if(((BarrelBlockEntity)level.getBlockEntity(S.north())).getItem(0).getCount()!=17)throw new AssertionError("Steady redstone repeated requester order");});context.takeScreenshot("create-vulkan-redstone-requester-accepted");
        context.runOnClient(client->{if(client.player.getInventory().getItem(9).getCount()!=12||client.player.getInventory().getItem(10).getCount()!=4)throw new AssertionError("Ghost requester samples consumed real items");});
        server.runCommand("item replace entity @p weapon.mainhand with create:wrench");context.waitFor(client->client.player.getMainHandItem().is(AllItems.WRENCH),200);lookAt(context,Vec3.atCenterOf(P).add(0,.499,0));context.waitFor(client->client.hitResult instanceof BlockHitResult hit&&hit.getBlockPos().equals(P)&&hit.getDirection()==Direction.UP,200);context.getInput().pressKey(options->options.keyUse);context.waitFor(client->client.gui.screen()==null&&client.level.getBlockState(P).getValue(RedstoneRequesterBlock.AXIS)==Direction.Axis.Z,200);
        var reload=context.computeOnClient(client->client.reloadResourcePacks());context.waitFor(client->reload.isDone()&&client.gui.overlay()==null,600);context.runOnClient(client->{if(client.getModelManager().getBlockStateModelSet().get(client.level.getBlockState(P))==client.getModelManager().getBlockStateModelSet().missingModel())throw new AssertionError("Requester lost model after reload");});server.runCommand("gamemode spectator @p");chunkUnload(context,world);
    }
    private static void station(net.minecraft.server.level.ServerLevel level,BlockPos pos,UUID id,int stock) { level.setBlockAndUpdate(pos.north(),Blocks.BARREL.defaultBlockState());((BarrelBlockEntity)level.getBlockEntity(pos.north())).setItem(0,new ItemStack(Items.APPLE,stock));level.setBlockAndUpdate(pos,AllBlocks.PACKAGER.defaultBlockState().setValue(PackagerBlock.FACING,Direction.SOUTH));level.setBlockAndUpdate(pos.above(),AllBlocks.STOCK_LINK.defaultBlockState());var link=(PackagerLinkBlockEntity)level.getBlockEntity(pos.above());link.behaviour.setFrequency(id);link.initialize(); }
    private static void chunkUnload(ClientGameTestContext context,TestSingleplayerContext world) {
        var pos=new BlockPos(1983,4,5);var source=pos.east();if(pos.getX()>>4==source.getX()>>4)throw new AssertionError("Requester fixture must cross a chunk boundary");var id=UUID.randomUUID();var server=world.getServer();var fullReads=new java.util.concurrent.atomic.AtomicInteger();server.runCommand("tp @p 1983 9 12");context.waitFor(client->Math.abs(client.player.getX()-1983.5)<.1,300);waitChunks(context,world,pos,source);
        server.runOnServer(ignored->{var expectedLevel=world.getConnection().getServerLevel();net.fabricmc.fabric.api.event.lifecycle.v1.ServerChunkEvents.FULL_CHUNK_STATUS_CHANGE.register((level,chunk,previous,next)->{
            if(level!=expectedLevel||previous.isOrAfter(net.minecraft.server.level.FullChunkStatus.FULL)||!next.isOrAfter(net.minecraft.server.level.FullChunkStatus.FULL)||chunk.getPos().x()!=source.getX()>>4||chunk.getPos().z()!=source.getZ()>>4)return;
            // This runs before FULL conversion's own future completes: blocking lookup deadlocks.
            LoadedLevelAccess.blockState(level,source.above());LoadedLevelAccess.blockEntity(level,source.above());fullReads.incrementAndGet();
        });});
        server.runOnServer(ignored->{var level=world.getConnection().getServerLevel();station(level,source,id,17);level.setBlockAndUpdate(pos,AllBlocks.REDSTONE_REQUESTER.defaultBlockState());var requester=(RedstoneRequesterBlockEntity)level.getBlockEntity(pos);requester.behaviour.setFrequency(id);level.getChunkSource().addTicket(new net.minecraft.server.level.Ticket(net.minecraft.server.level.TicketType.FORCED,33),new net.minecraft.world.level.ChunkPos(pos.getX()>>4,pos.getZ()>>4));});server.runCommand("tp @p 5000 10 5000");var unloaded=new AtomicBoolean();
        for(int i=0;i<120&&!unloaded.get();i++){context.waitTicks(5);server.runOnServer(ignored->{var level=world.getConnection().getServerLevel();var requester=(RedstoneRequesterBlockEntity)LoadedLevelAccess.blockEntity(level,pos);requester.tick();requester.onRedstonePowerChanged();requester.getAccurateSummary();unloaded.set(!level.isLoaded(source));});}
        if(!unloaded.get()){
            server.runOnServer(ignored->{var level=world.getConnection().getServerLevel();var chunk=new net.minecraft.world.level.ChunkPos(source.getX()>>4,source.getZ()>>4);Create.LOGGER.error("Requester source chunk: {}, tickets: {}",level.getChunkSource().getChunkDebugData(chunk),level.getDataStorage().computeIfAbsent(net.minecraft.world.level.TicketStorage.TYPE).getTickets(chunk.pack()));});
            throw new AssertionError("Requester stock scans kept neighbor source chunk loaded");
        }
        server.runOnServer(ignored->{var level=world.getConnection().getServerLevel();var requester=(RedstoneRequesterBlockEntity)LoadedLevelAccess.blockEntity(level,pos);if(requester.getAccurateSummary().getCountOf(new ItemStack(Items.APPLE))!=0||GlobalLogisticsManager.get(level).getUnloadedLinkCount(id)!=1)throw new AssertionError("Requester counted an unloaded source or registered itself as a source");});
        server.runCommand("tp @p 1983 9 12");context.waitFor(client->Math.abs(client.player.getX()-1983.5)<.1&&client.level.getBlockEntity(source) instanceof PackagerBlockEntity,400);waitChunks(context,world,pos,source);context.waitTicks(5);server.runOnServer(ignored->{var level=world.getConnection().getServerLevel();if(fullReads.get()==0)throw new AssertionError("FULL conversion callback was not exercised");if(((RedstoneRequesterBlockEntity)level.getBlockEntity(pos)).getAccurateSummary().getCountOf(new ItemStack(Items.APPLE))!=17)throw new AssertionError("Requester stock did not recover");level.getChunkSource().removeTicketWithRadius(net.minecraft.server.level.TicketType.FORCED,new net.minecraft.world.level.ChunkPos(pos.getX()>>4,pos.getZ()>>4),0);});
    }
    private static void open(ClientGameTestContext context) { context.getInput().pressKey(options->options.keyUse);context.waitFor(client->client.gui.screen() instanceof RedstoneRequesterScreen,200);context.waitTicks(2); }
    private static void lookAt(ClientGameTestContext context,Vec3 point) { var rotation=context.computeOnClient(client->{var delta=point.subtract(client.player.getEyePosition());return new Vec2((float)Math.toDegrees(Math.atan2(-delta.x,delta.z)),(float)-Math.toDegrees(Math.atan2(delta.y,Math.hypot(delta.x,delta.z))));});context.getInput().lookAt(rotation.x,rotation.y); }
    private static void shiftClick(ClientGameTestContext context,int index) { context.runOnClient(client->{var screen=(RedstoneRequesterScreen)client.gui.screen();var point=screen.slotPosition(index);var event=new net.minecraft.client.input.MouseButtonEvent(point.x,point.y,new net.minecraft.client.input.MouseButtonInfo(InputConstants.MOUSE_BUTTON_LEFT,InputConstants.MOD_SHIFT));screen.mouseClicked(event,false);screen.mouseReleased(event);}); }
    private static void waitChunks(ClientGameTestContext context,TestSingleplayerContext world,BlockPos a,BlockPos b) { var ready=new AtomicBoolean();for(int i=0;i<300&&!ready.get();i++){world.getServer().runOnServer(ignored->{var level=world.getConnection().getServerLevel();ready.set(level.isLoaded(a)&&level.isLoaded(b));});if(!ready.get())context.waitTicks(1);}if(!ready.get())throw new AssertionError("Requester chunks unavailable"); }
}
